# Q17: add the red-ridge origin results (s104a-d) to /output/report.json. Re-runnable: starts from out/report_before_q17.json (first run saves it).
import json,shutil,os
R='/output/report.json'; B='/workspace/out/report_before_q17.json'
if not os.path.exists(B): shutil.copy(R,B)
r=json.load(open(B)); res=[x for x in r['results'] if not x['evidence'].startswith('Q17:')]
O='/workspace/out/q17/'; a=json.load(open(O+'s104a.json')); b=json.load(open(O+'s104b.json')); c=json.load(open(O+'s104c.json'))
A=lambda n,v:{'name':n,'value':v}
com=[A('distance','D=40 Mpc, 1"=194 pc; VSYS=2780 km/s radio-LSRK'),
 A('data','Xb4d (0.94x0.74") pbcor cubes HCN 3-2 spw27, HCO+ 3-2 spw25, convolved (flux rescaled) to a circular 1.05" beam; per-pixel baseline = median(-900..-450 km/s); velocities about VSYS'),
 A('noise','per channel from line-free channels of the same aperture spectrum (0.29-0.50 mJy/beam, r=0.75-1" mean, 4.4 km/s channels); aperture-flux errors from the field scatter of random r=1" apertures (s77); channel noise is Hanning-correlated, MC velocity errors inflated x1.5'),
 A('axis','PA 185 deg through S (offset positive north); ridge position = 0.15" E, 3.3" N of S; lobe = 0.15" E, 1.85" S of S (Q2r2 definitions)')]
def add(q,t,v,u,un,conf,ev,extra=()):
    res.append(dict(quantity=q,target=t,value=v,uncertainty=u,unit=un,assumptions=com+list(extra),confidence=conf,evidence='Q17: '+ev))
sH=a['HCN_slopes']; sO=a['HCO+_slopes']; k=lambda m,key:b[f'{m}|{key}']
# ---- 1 kinematics
add('Kinematics of the red dense-gas ridge (+1.5..+6.5" N of S) vs the blue lobe: velocity centroid, width and PV structure along the S-N axis; Bridge/rotation continuity',
 'ridge 3.3" N of S (640 pc), blue lobe 1.85" S of S (360 pc); HCN, HCO+ 3-2',
 ('(1) Flux-weighted mean velocity of the wing (150..400 km/s, r=0.75" apertures every 0.5" along PA 185): RED ridge +1.5..+4.0" N of S: HCN <v>=%+.0f+-%.0f km/s with slope %+.1f+-%.1f km/s/arcsec (chi2 %.1f/4, i.e. NO velocity gradient), HCO+ %+.0f+-%.0f, slope %+.0f+-%.0f; BLUE lobe -3.0..-1.0" S of S: HCN %+.0f+-%.0f (slope %+.1f+-%.1f), HCO+ %+.0f+-%.0f. At the r=1" peak apertures: ridge HCN %+.0f+-%.0f, HCO+ %+.0f+-%.0f; lobe HCN %+.0f+-%.0f, HCO+ %+.0f+-%.0f km/s. |v| of the ridge and the lobe are equal within errors (HCN 258+-5 vs 249+-4 km/s: mirror-symmetric about VSYS, difference +9+-6; HCO+ 244+-9 vs 225+-5). Toward N the red <v> falls to +217/+208 (HCN) at +5.0/+5.5" where the N wing (r=1" at N: <v>=+223+-17 HCN) takes over. (2) The ridge sits on the BRIDGE core (the core flux -150..150 is %.2f Jy km/s HCN vs %.2f at the lobe) but the core line-peak velocity there is %+.0f km/s (range %+.0f..%+.0f, r<1.5", >5 sigma; HCO+ %+.0f, %+.0f..%+.0f): the ridge is displaced by +250 km/s = 4-5 core FWHM from the local gas and 3-4x the whole velocity range of the core there; the s77g rotation null model predicts <=0.04 Jy km/s for sigma_n<=60 km/s vs 0.20-0.22 observed. No velocity continuity with the Bridge: the core has no gradient reaching +100..+250 (PV figure), and the +120..+360 wing is a separate high-velocity tail (wing/core %.1f%% HCN, %.1f%% HCO+ at |v|=180..320 vs %.0f%% / %.0f%% at the lobe, where the core is weak). (3) Spectral shape beyond |v|>200 the ridge and lobe spectra (mirrored) are indistinguishable in amplitude (~1 mJy/beam, both lines) and fall off alike; at 120-200 km/s the ridge is lower relative to its 200-280 km/s level: (120-200)/(200-280) = %.2f+-%.2f (HCN), %.2f+-%.2f (HCO+) vs the lobe %.2f+-%.2f, %.2f+-%.2f (2.6 sigma HCN, 4.1 sigma HCO+; the ridge profile peaks at ~+240, the lobe profile decreases monotonically from the core; the inner channels of the ridge are partly under the bright Bridge core so this is not clean).'
   %(sH['red_1p5_4p0']['mean'],sH['red_1p5_4p0']['mean_err'],sH['red_1p5_4p0']['slope'],sH['red_1p5_4p0']['slope_err'],sH['red_1p5_4p0']['chi2'],
     sO['red_1p5_4p0']['mean'],sO['red_1p5_4p0']['mean_err'],sO['red_1p5_4p0']['slope'],sO['red_1p5_4p0']['slope_err'],
     sH['blue_m3_m1']['mean'],sH['blue_m3_m1']['mean_err'],sH['blue_m3_m1']['slope'],sH['blue_m3_m1']['slope_err'],sO['blue_m3_m1']['mean'],sO['blue_m3_m1']['mean_err'],
     k('HCN','ridge|red')['mv'],k('HCN','ridge|red')['mv_err'],k('HCO+','ridge|red')['mv'],k('HCO+','ridge|red')['mv_err'],k('HCN','lobe|blue')['mv'],k('HCN','lobe|blue')['mv_err'],k('HCO+','lobe|blue')['mv'],k('HCO+','lobe|blue')['mv_err'],
     k('HCN','core')['ridge'],k('HCN','core')['lobe'],k('HCN','core_vfield_ridge')['median'],k('HCN','core_vfield_ridge')['lo'],k('HCN','core_vfield_ridge')['hi'],k('HCO+','core_vfield_ridge')['median'],k('HCO+','core_vfield_ridge')['lo'],k('HCO+','core_vfield_ridge')['hi'],
     b['HCN|180-320']['ridge']/b['HCN|core']['ridge']*100,b['HCO+|180-320']['ridge']/b['HCO+|core']['ridge']*100,b['HCN|180-320']['lobe']/b['HCN|core']['lobe']*100,b['HCO+|180-320']['lobe']/b['HCO+|core']['lobe']*100,
     0.62,0.10,0.66,0.12,1.08,0.14,1.91,0.28)),
 'mean-v errors from white-noise MC x1.5; see text for slopes','km/s','medium','s104a_q17_pv.py -> out/q17/s104a.txt/json, s104b -> s104b.txt, s104d_q17_figs.py -> out/q17/s104_pv_spectra.png, s104d.txt; s77g (rotation null)',
 [A('mean velocity window','150..400 km/s about VSYS on the red side (ridge, N) and -400..-150 (lobe); wing-core overlap excluded by |v|>=150'),A('core velocity','line-peak velocity of the per-pixel spectrum within |v|<150 km/s, Xb4d at 1.05", >5 sigma')])
# ---- 2 comparison + hypotheses
rH=b['HCN|180-320']; rO=b['HCO+|180-320']
add('Is the red ridge the S counter-lobe, N outflow or Bridge gas? Flux, HCN/HCO+, 3-2/1-0 excitation, geometry and the consequences of each hypothesis',
 'red ridge (OF-Red of Michiyama+2018) vs South-OF-Blue lobe; N wing; Bridge',
 ('MATCHED MIRRORED WINDOWS (|v|=180..320, r=1" at 1.05"): HCN ridge %.3f+-%.3f vs lobe %.3f+-%.3f Jy km/s (ridge/lobe %.2f+-0.10); HCO+ ridge %.3f+-%.3f vs lobe %.3f+-%.3f (%.2f+-0.21); weighted mean ridge/lobe %.2f+-%.2f. HCN/HCO+ (T_b, matched J and beam; x1.013 for nu^2): ridge %.2f+-0.24, lobe %.2f+-0.25 (150-350 window: %.2f vs %.2f): same within 1 sigma. The mirror position 1.85" N of S holds only 0.128 (HCN) / 0.083 (HCO+) Jy km/s (40%%/40%% of the lobe), so the red emission is a clump 1.7x farther from S than the blue one, not a mirror image in position. 2D fits (ridge beam-shaped component + fixed N and S): ridge centroid dE=%+.2f+-0.34", dN=%+.2f+-0.34" from S (r=%.1f" = %.0f pc, PA %.0f deg; HCO+ PA %.0f), intrinsic FWHM %.1f+-0.8" (unresolved-to-marginal); lobe (-320..-180): dE=%+.2f+-0.19, dN=%+.2f+-0.19 (r=%.1f", PA %.0f deg): ridge and lobe are antiparallel within ~%.0f deg (+-8) about S, and the ridge lies %.1f" S of N (PA from N %.0f deg). LITERATURE 3-2/1-0 (M18 OF-Red 1-0 HCN/HCO+ 0.08+-0.02 each, [240,360]): T_b ratio r31 at OF-Red (r=1.05"-2.1" apertures) HCN %.2f+-%.2f to %.2f+-%.2f, HCO+ %.2f+-%.2f to %.2f+-%.2f vs the same procedure at South-OF-Blue HCN %.2f+-%.2f to %.2f+-%.2f, HCO+ %.2f+-%.2f to %.2f+-%.2f, i.e. the ridge is 1.5-2 sigma LOWER excitation (ratio of ratios 0.4-0.8; M18 also give CO R32/10=0.7+-0.1 at OF-Red vs 1.3+-0.2 at South-OF-Blue, and CO R21/10 0.9 vs 1.2) but the 1-0 beam/aperture match is unverified; M18 HCN/HCO+(1-0) 0.99+-0.34 (OF-Red) vs 0.68+-0.24 (lobe): consistent. HYPOTHESES: (A) S counter-lobe: predicts |v| equal to the lobe (OBSERVED 258 vs 249 km/s, same within ~10), HCN/HCO+ equal (obs. yes), flux ratio ~1 (0.8+-0.1, with a flux budget in the same window), antiparallel on the S axis (PA 2+-6 vs 183-189 deg: yes), constant |v| with radius (no gradient in either): all met; unexplained: 1.7x larger radius, lower 3-2/1-0 (1.5-2 sigma) and the weaker 120-200 km/s part. (B) N outflow / red flank of N: the red wing at N is one-sided (blue 150-350 at N <0.73%% of the core vs red 1.9%%, Q2r2), the ridge peak is a separate clump 1.8" (3.6 beams) S of N whose |v| (257) exceeds that at N (+223+-17), so it is not the extension of the N line profile; M18 place the N blue lobe at PA 291 deg from N (2.4" NW), the expected counter-direction (PA ~111 deg) is ~70 deg from the ridge (PA ~182 deg from N). It requires a unipolar, S-pointing red-only N flow of the same speed as the S lobe: possible only for a strongly asymmetric N outflow; not excluded. (C) Bridge/tidal gas: needs +250 km/s relative to the local gas (core -1..-9 km/s), >4x the core velocity range and the rotation null fails; the S-N line is also the S outflow axis (PA 183-189 vs S->N 178-185), so the collinearity is no discriminant between A, B and C; the kinematics can not separate a bridge streaming flow from an outflow, but the equal-and-opposite |v| and equal HCN/HCO+ favour (A). VERDICT: the ridge is most consistent with the red (counter) lobe of the S outflow, i.e. bipolar in |v|, line ratio and flux (0.8+-0.1 of the blue lobe), asymmetric in radius (3.3" vs 1.9"); a N-flow contribution or a bridge origin cannot be excluded with these data (N-only would need an unipolar flow, Bridge a 250 km/s streaming); keep as probable-not-proven.'
   %(rH['ridge'],rH['ridge_e'],rH['lobe'],rH['lobe_e'],rH['ridge']/rH['lobe'],rO['ridge'],rO['ridge_e'],rO['lobe'],rO['lobe_e'],rO['ridge']/rO['lobe'],0.80,0.09,
     1.0127*rH['ridge']/rO['ridge'],1.0127*rH['lobe']/rO['lobe'],1.0127*b['HCN|150-350']['ridge']/b['HCO+|150-350']['ridge'],1.0127*b['HCN|150-350']['lobe']/b['HCO+|150-350']['lobe'],
     b['HCN|fit2d|ridge180-320']['dE'],b['HCN|fit2d|ridge180-320']['dN'],b['HCN|fit2d|ridge180-320']['r'],b['HCN|fit2d|ridge180-320']['r']*194,b['HCN|fit2d|ridge180-320']['PA'],b['HCO+|fit2d|ridge180-320']['PA'],b['HCN|fit2d|ridge180-320']['fwhm_int'],
     b['HCN|fit2d|lobe-320..-180']['dE'],b['HCN|fit2d|lobe-320..-180']['dN'],b['HCN|fit2d|lobe-320..-180']['r'],b['HCN|fit2d|lobe-320..-180']['PA'],abs((b['HCN|fit2d|ridge180-320']['PA']+180)%360-b['HCN|fit2d|lobe-320..-180']['PA'])+0,1.8,182,
     c['HCN|OF-Red|1.05']['r31'],c['HCN|OF-Red|1.05']['e_r31'],c['HCN|OF-Red|2.1']['r31'],c['HCN|OF-Red|2.1']['e_r31'],c['HCO+|OF-Red|1.05']['r31'],c['HCO+|OF-Red|1.05']['e_r31'],c['HCO+|OF-Red|2.1']['r31'],c['HCO+|OF-Red|2.1']['e_r31'],
     c['HCN|South-OF-Blue|1.05']['r31'],c['HCN|South-OF-Blue|1.05']['e_r31'],c['HCN|South-OF-Blue|2.1']['r31'],c['HCN|South-OF-Blue|2.1']['e_r31'],c['HCO+|South-OF-Blue|1.05']['r31'],c['HCO+|South-OF-Blue|1.05']['e_r31'],c['HCO+|South-OF-Blue|2.1']['r31'],c['HCO+|South-OF-Blue|2.1']['e_r31'])),
 'flux ratio +-0.09 (statistical; flux-scale systematic 8% cancels in the ratio, residual-dominated wing: Q2r2); verdict qualitative','Jy km/s, ratio','low','s104b_q17_ridge_lobe.py -> out/q17/s104b.txt/json; s104c_q17_r31_mass.py -> s104c.txt; Michiyama+2018 Tables 1,3,4; Q2r2 s77f/s77g',
 [A('hypotheses','A S counter-lobe; B N outflow (red part / flank); C Bridge/tidal gas; no kinematic test separates B or C from A by geometry alone because N, the ridge and S are collinear')])
# ---- 3 mass
add('Dense-gas mass, mass-loss rate and momentum of the red ridge relative to the blue lobe (same RADEX scaling), and the resulting bipolar bookkeeping for the S outflow',
 'ridge (|v|=180..360, 3.3" N of S) scaled from the S lobe window -360..-180',
 ('Same RADEX scaling as the lobe (Q2r2: dense mass in -360..-180 = 2.1e6 (HCO+ X=1e-8) .. 7.0e6 Msun (X(HCO+)=3e-9); gas excitation assumed equal since HCN/HCO+ are equal): ridge/lobe flux ratio 0.80+-0.09 -> M_ridge(180..360) = 1.7e6 .. 5.6e6 Msun (factor ~2.6 from the abundance prior, +-11%% from the flux ratio; lower by up to ~0.4-0.8 if the ridge excitation is the lower one (r31 0.4-0.8x), i.e. non-LTE mass can differ by a factor ~2 up or down with excitation). Total in the same window for the two lobes: 3.8e6 .. 1.3e7 Msun (x1.8 of the blue lobe). Bookkeeping with Mdot = M v_los tan i / R_proj (Q2r2): v_los 253 (lobe) / 257 (ridge) km/s, R_proj 1.88" (365 pc) / 3.3" (640 pc): for i=80 deg: lobe 8.4-28 Msun/yr, ridge 3.9-13 Msun/yr (ratio 0.46), i=70 / 85: x0.5 / x2; bipolar S total Mdot(window) = 1.5x the lobe alone (12-41 Msun/yr at i=80); momentum (los) p_ridge/p_lobe = 0.81 (p_lobe %s Msun km/s): momentum is bipolar-balanced to ~20%%, the dynamical (projected) age of the ridge is 1.75x the lobe (%s Myr vs %s at i=80), so either the red lobe is older/faster-travelled or the flow is not symmetric. The mass is a model-scaled number (no independent lobe-like non-LTE fit for the ridge: ridge r31 only from the M18 1-0 windows and 3-2 at 1.05"); the ridge-only window mass is a lower limit for a lobe-like wide profile: scaling to the full lobe profile (broad component/window = 3.7) would give 6e6..2e7 Msun.'%('5.3e8-1.8e9','0.43','0.25')),
 'ridge/lobe +-11%; absolute mass factor ~2.6 (X prior) x 2 (excitation); Mdot spans 1.5 dex with i','Msun, Msun/yr, Msun km/s','low','s104c_q17_r31_mass.py -> out/q17/s104c.txt; Q2r2 report entries (s77e, s75c)',
 [A('mass scaling','M_ridge = M_lobe(window) x flux ratio (matched |v|=180..320 window, r=1" apertures, HCN and HCO+ weighted mean); same excitation'),A('inclination','i=80 (70-85) deg between outflow axis and line of sight, as in Q2r2')])
r['results']=res; json.dump(r,open(R,'w'),indent=1); print(len(res))
